'use strict';

const { test } = require('node:test');
const assert = require('node:assert/strict');
const http = require('node:http');
const fs = require('node:fs');
const path = require('node:path');
const { createTeamBridge } = require('../server/team-bridge');

// Verbatim synthetic replies generated by portfolio_mcp.rs against the real
// awr-server binary and its PostgreSQL fixture. Do not replace these with a
// hand-written demonstration shape.
function sample(name) {
  return JSON.parse(fs.readFileSync(path.join(__dirname, 'fixtures', `portfolio-web-${name}.json`), 'utf8'));
}
const MEMBER = sample('member');
const PAGED = sample('paged');
const PAGE_2 = sample('page-2');
const AGENT = sample('agent');
const FIXTURE_DIR = path.resolve(__dirname, '../../../tests/fixtures/workstreams/team-web-loop');

async function startUpstream(handler) {
  const server = http.createServer(handler);
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
  return {
    base: `http://127.0.0.1:${server.address().port}`,
    close: () => new Promise((resolve) => {
      server.close(resolve);
      server.closeAllConnections();
    }),
  };
}

async function startBridge(teamUrl, now) {
  const bridge = createTeamBridge({ teamUrl, teamFixtureDir: FIXTURE_DIR, port: 0, now });
  const server = http.createServer(async (req, res) => {
    const url = new URL(req.url, 'http://127.0.0.1');
    const handler = bridge.routes[`${req.method} ${url.pathname}`];
    if (!handler) {
      res.writeHead(404, { 'content-type': 'application/json' });
      res.end('{}');
      return;
    }
    try {
      const json = await handler(url, null, req, res);
      res.writeHead(200, { 'content-type': 'application/json' });
      res.end(JSON.stringify(json));
    } catch (error) {
      res.writeHead(500, { 'content-type': 'application/json' });
      res.end(JSON.stringify({ ok: false, error: { message: String(error.message || error) } }));
    }
  });
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
  return {
    base: `http://127.0.0.1:${server.address().port}`,
    close: () => new Promise((resolve) => {
      server.close(resolve);
      server.closeAllConnections();
    }),
  };
}

async function read(base, pathname, cookie) {
  const response = await fetch(base + pathname, {
    headers: cookie ? { cookie: `awr_web_session=${cookie}` } : {},
  });
  return response.json();
}

function jsonReply(response, body, status = 200) {
  response.writeHead(status, { 'content-type': 'application/json' });
  response.end(JSON.stringify(body));
}

function collectBody(request, callback) {
  const chunks = [];
  request.on('data', (chunk) => chunks.push(chunk));
  request.on('end', () => callback(JSON.parse(Buffer.concat(chunks).toString('utf8') || '{}')));
}

test('portfolio bridge preserves real member and paged replies with read coverage', async () => {
  const calls = [];
  const upstream = await startUpstream((request, response) => {
    if (request.url === '/v1/web/session') {
      jsonReply(response, { ok: true, session_id: 'ws_member', expires_at_ms: MEMBER.data.as_of.at_unix_ms + 60000 });
      return;
    }
    if (request.url === '/v1/web/portfolio/overview' && request.method === 'POST') {
      collectBody(request, (body) => {
        calls.push({ body, cookie: request.headers.cookie });
        const reply = body.cursor ? PAGE_2 : body.limit === 1 ? PAGED : MEMBER;
        jsonReply(response, reply);
      });
      return;
    }
    jsonReply(response, { code: 'NotFound' }, 404);
  });
  const now = MEMBER.data.as_of.at_unix_ms + 1000;
  const bridge = await startBridge(upstream.base, () => now);
  try {
    const full = await read(bridge.base, '/api/team/portfolio', 'ws_member');
    assert.equal(full.ok, true);
    assert.deepEqual(full.result, MEMBER);
    assert.equal(full.read_at_unix_ms, now);
    assert.deepEqual(full.coverage, {
      status: 'complete', returned_projects: 2, total_projects: 2,
      not_read_projects: 0, truncated: false, next_cursor: null,
    });
    assert.deepEqual(full.freshness, {
      report_received: { status: 'not_measured' },
      authoritative: { status: 'measured', stale_after_ms: 120000, age_ms: 1000, at_unix_ms: MEMBER.data.as_of.at_unix_ms },
      page_read: { status: 'measured', at_unix_ms: now },
    });

    const first = await read(bridge.base, '/api/team/portfolio?limit=1', 'ws_member');
    assert.deepEqual(first.result, PAGED);
    assert.equal(first.coverage.status, 'partial');
    assert.equal(first.coverage.truncated, true);
    const cursor = encodeURIComponent(PAGED.data.next_cursor);
    const second = await read(bridge.base, `/api/team/portfolio?limit=1&cursor=${cursor}`, 'ws_member');
    assert.deepEqual(second.result, PAGE_2);
    assert.equal(second.coverage.truncated, false);
    assert.notEqual(second.result.data.projects[0].project_id, first.result.data.projects[0].project_id);
    assert.deepEqual(calls.map((call) => call.body), [
      { protocol_version: 1 },
      { protocol_version: 1, limit: 1 },
      { protocol_version: 1, limit: 1, cursor: PAGED.data.next_cursor },
    ]);
    assert.ok(calls.every((call) => call.cookie === 'awr_web_session=ws_member'));

    const beforeInvalid = calls.length;
    for (const pathname of [
      '/api/team/portfolio?limit=0', '/api/team/portfolio?limit=201',
      '/api/team/portfolio?limit=1.5', '/api/team/portfolio?limit=01',
      '/api/team/portfolio?limit=1&limit=2', '/api/team/portfolio?cursor=',
      '/api/team/portfolio?unexpected=1',
    ]) {
      const invalid = await read(bridge.base, pathname, 'ws_member');
      assert.equal(invalid.ok, false);
      assert.equal(invalid.error.code, 'InvalidInput');
      assert.equal(invalid.result, undefined);
    }
    assert.equal(calls.length, beforeInvalid, 'invalid selectors never reach the service');
  } finally {
    await bridge.close();
    await upstream.close();
  }
});

test('portfolio reads are session-isolated and revocation or upstream failure clears old content', async () => {
  const active = new Set(['ws_one', 'ws_two']);
  const portfolioCalls = [];
  let mode = 'live';
  const upstream = await startUpstream((request, response) => {
    const cookie = request.headers.cookie || '';
    const sessionId = cookie.split('awr_web_session=')[1]?.split(';')[0];
    if (request.url === '/v1/web/session') {
      if (!active.has(sessionId)) {
        jsonReply(response, { code: 'SessionExpired', message: 'web session expired or revoked' }, 401);
      } else {
        jsonReply(response, { ok: true, session_id: sessionId, expires_at_ms: AGENT.data.as_of.at_unix_ms + 60000 });
      }
      return;
    }
    if (request.url === '/v1/web/portfolio/overview') {
      collectBody(request, () => {
        portfolioCalls.push(sessionId);
        if (mode === 'disconnect') {
          request.socket.destroy();
          return;
        }
        if (mode === 'denied') {
          jsonReply(response, { code: 'Forbidden', message: 'access denied' }, 403);
          return;
        }
        if (mode === 'failed') {
          jsonReply(response, { code: 'Busy', message: 'temporarily unavailable' }, 503);
          return;
        }
        jsonReply(response, sessionId === 'ws_one' ? MEMBER : AGENT);
      });
      return;
    }
    jsonReply(response, { code: 'NotFound' }, 404);
  });
  const bridge = await startBridge(upstream.base, () => AGENT.data.as_of.at_unix_ms + 1000);
  try {
    const one = await read(bridge.base, '/api/team/portfolio', 'ws_one');
    const two = await read(bridge.base, '/api/team/portfolio', 'ws_two');
    assert.deepEqual(one.result, MEMBER);
    assert.deepEqual(two.result, AGENT);
    assert.equal(two.coverage.status, 'partial');
    assert.equal(two.coverage.not_read_projects, 1);
    const oneAgain = await read(bridge.base, '/api/team/portfolio', 'ws_one');
    assert.deepEqual(oneAgain.result, MEMBER);
    assert.deepEqual(portfolioCalls, ['ws_one', 'ws_two', 'ws_one'],
      'every read reaches upstream; no member result crosses a cookie session');

    active.delete('ws_one');
    const revoked = await read(bridge.base, '/api/team/portfolio', 'ws_one');
    assert.equal(revoked.ok, false);
    assert.equal(revoked.error.code, 'SessionExpired');
    assert.equal(revoked.result, undefined);
    assert.equal(revoked.coverage, undefined);
    assert.equal(portfolioCalls.length, 3, 'a revoked session is refused before the portfolio read');
    assert.ok(!JSON.stringify(revoked).includes('portfolio-project-001'));

    mode = 'denied';
    const denied = await read(bridge.base, '/api/team/portfolio', 'ws_two');
    assert.equal(denied.ok, false);
    assert.equal(denied.error.code, 'Forbidden');
    assert.equal(denied.result, undefined);
    assert.ok(!JSON.stringify(denied).includes('portfolio-project-001'));

    mode = 'failed';
    const failed = await read(bridge.base, '/api/team/portfolio', 'ws_two');
    assert.equal(failed.ok, false);
    assert.equal(failed.error.code, 'Busy');
    assert.equal(failed.result, undefined);
    assert.equal(failed.freshness.authoritative.status, 'failed');
    assert.ok(!JSON.stringify(failed).includes('portfolio-project-001'));

    mode = 'disconnect';
    const disconnected = await read(bridge.base, '/api/team/portfolio', 'ws_two');
    assert.equal(disconnected.ok, false);
    assert.equal(disconnected.error.code, 'BadGateway');
    assert.equal(disconnected.result, undefined);
    assert.ok(!JSON.stringify(disconnected).includes('portfolio-project-001'));

    mode = 'live';
    const restored = await read(bridge.base, '/api/team/portfolio', 'ws_two');
    assert.deepEqual(restored.result, AGENT);
  } finally {
    await bridge.close();
    await upstream.close();
  }
});

test('portfolio fixtures contain no credentials or private source prose', () => {
  for (const fixture of [MEMBER, PAGED, PAGE_2, AGENT]) {
    const text = JSON.stringify(fixture);
    assert.ok(!text.includes('PRIVATE NEXT ACTION'));
    for (const banned of ['secret', 'password', 'bearer']) {
      assert.ok(!text.toLowerCase().includes(banned));
    }
  }
});
